
"""Interactive map of Norwegian electricity price areas."""

import json
from pathlib import Path

import streamlit as st
import pydeck as pdk

import copy
import pandas as pd
import requests

st.title("Interactive Map", icon=":material/map:")
st.write(
    "Explore Norwegian electricity price areas and their "
    "geographic boundaries."
)

# Locate the GeoJSON file generated by prepare_geojson.py.
ROOT = Path(__file__).resolve().parents[2]
GEOJSON_PATH = ROOT / "data" / "geojson" / "price_areas.geojson"


@st.cache_data
def load_geojson(path):
    """Read geographic boundaries without repeating file operations."""
    with open(path, encoding="utf-8") as file:
        return json.load(file)


# Load the five electricity price-area polygons.
price_areas = load_geojson(str(GEOJSON_PATH))

# Remember the selected region across Streamlit pages.
if "map_selected_region" not in st.session_state:
    st.session_state["map_selected_region"] = None


@st.cache_data(ttl=3600)
def load_reservoir_filling():
    """Download weekly filling measurements for electricity areas."""

    url = (
        "https://biapi.nve.no/magasinstatistikk/api/"
        "Magasinstatistikk/HentOffentligData"
    )

    response = requests.get(url, timeout=60)
    response.raise_for_status()

    data = pd.DataFrame(response.json())

    # Keep electricity-area measurements only.
    data = data[data["omrType"] == "EL"].copy()
    data["date"] = pd.to_datetime(data["dato_Id"])
    data["omrnr"] = pd.to_numeric(data["omrnr"])
    data["fyllingsgrad"] = pd.to_numeric(data["fyllingsgrad"])
    data["iso_aar"] = pd.to_numeric(data["iso_aar"])
    data["iso_uke"] = pd.to_numeric(data["iso_uke"])

    return data


@st.cache_data
def load_weekly_weather():
    """Aggregate saved hourly ERA5 observations into Norwegian ISO weeks."""

    weekly_frames = []

    for region in ["NO1", "NO2", "NO3"]:
        path = ROOT / "data" / f"weather_{region}_2024_100locations.parquet"

        if not path.exists():
            continue

        weather = pd.read_parquet(path)

        # Convert UTC observations to Norwegian local time.
        weather["time"] = (
            pd.to_datetime(weather["time"], utc=True)
            .dt.tz_convert("Europe/Oslo")
        )

        # Use ISO year and week to match NVE reservoir reporting periods.
        iso = weather["time"].dt.isocalendar()
        weather["iso_year"] = iso.year
        weather["iso_week"] = iso.week

        weekly = (
            weather.groupby(["iso_year", "iso_week"], as_index=False)
            .agg(
                temperature_c=("temperature_2m", "mean"),
                precipitation_mm=("precipitation", "sum")
            )
        )

        weekly["region"] = region
        weekly_frames.append(weekly)

    if not weekly_frames:
        return pd.DataFrame()

    return pd.concat(weekly_frames, ignore_index=True)

weekly_weather = load_weekly_weather()

st.subheader("Weekly Weather Data — Test")
st.dataframe(weekly_weather.head(12), hide_index=True)


try:
    reservoir_data = load_reservoir_filling()
except (requests.RequestException, ValueError) as error:
    st.error(f"Could not load reservoir statistics: {error}")
    st.stop()


# Load weather only when a weather-based colour mode is selected.
weekly_weather = (
    load_weekly_weather()
    if color_mode in weather_modes
    else pd.DataFrame()
)

date_source = reservoir_data

if color_mode in weather_modes:
    if weekly_weather.empty:
        st.warning("No saved weather data is available.")
        st.stop()

    # Match NVE reporting weeks to the available 2024 ERA5 weeks.
    weather_weeks = (
        weekly_weather[weekly_weather["iso_year"] == 2024]
        [["iso_year", "iso_week"]]
        .drop_duplicates()
    )

    date_source = reservoir_data.merge(
        weather_weeks,
        left_on=["iso_aar", "iso_uke"],
        right_on=["iso_year", "iso_week"],
        how="inner"
    )

available_dates = sorted(
    date_source["date"].dropna().unique(),
    reverse=True
)

if len(available_dates) == 0:
    st.warning("No matching reservoir and weather weeks found.")
    st.stop()


color_mode = st.radio(
    "Colour areas by",
    [
        "Reservoir filling",
        "Electricity price area",
        "Temperature",
        "Precipitation"
    ],
    horizontal=True
)

weather_modes = ["Temperature", "Precipitation"]

selected_date = st.selectbox(
    "Reservoir reporting week",
    options=available_dates,
    format_func=lambda d: pd.Timestamp(d).strftime("%d %B %Y")
)

# Get filling percentages for the selected week.
weekly_data = reservoir_data[
    reservoir_data["date"] == selected_date
]

filling_by_area = (
    weekly_data.set_index("omrnr")["fyllingsgrad"].to_dict()
)


if color_mode in weather_modes:
    property_column = (
        "temperature_c"
        if color_mode == "Temperature"
        else "precipitation_mm"
    )

    # Retrieve regional measurements for the selected ISO week.
    selected_weather = weekly_weather[
        (weekly_weather["iso_year"] == selected_iso_year) &
        (weekly_weather["iso_week"] == selected_iso_week)
    ]

    weather_by_area = (
        selected_weather.set_index("region")[property_column].to_dict()
    )

    # Keep the colour scale consistent when switching weeks.
    full_series = weekly_weather.loc[
        weekly_weather["iso_year"] == 2024,
        property_column
    ].dropna()

    weather_min = float(full_series.min())
    weather_max = float(full_series.max())


def filling_color(value):
    """Return an RGBA colour based on reservoir filling (0–1)."""

    return [
        int(235 - 185 * value),  # Red decreases
        int(110 + 55 * value),   # Green increases
        int(65 + 155 * value),   # Blue increases
        140                      # Transparency
    ]


def weather_color(value, minimum, maximum, mode):
    """Map weather measurements to semi-transparent RGB colours."""

    # Scale the measurement between 0 and 1.
    span = maximum - minimum
    fraction = (value - minimum) / span if span > 0 else 0.5
    fraction = max(0, min(1, fraction))

    if mode == "Temperature":
        # Blue = cold, orange/red = warm.
        return [
            int(60 + 175 * fraction),
            int(140 - 60 * fraction),
            int(230 - 165 * fraction),
            140
        ]

    # Light grey = dry, blue = wet.
    return [
        int(228 - 170 * fraction),
        int(229 - 85 * fraction),
        int(232 - 12 * fraction),
        140
    ]


# Copy the original boundaries so the cached data stays unchanged.
colored_areas = copy.deepcopy(price_areas)

# Distinct colours for identifying electricity price areas.
area_colors = {
    "NO1": [70, 130, 200, 140],
    "NO2": [65, 170, 130, 140],
    "NO3": [180, 115, 190, 140],
    "NO4": [230, 160, 65, 140],
    "NO5": [90, 175, 190, 140]
}


for feature in colored_areas["features"]:
    region = feature["properties"]["region"]
    area_number = int(region.replace("NO", ""))

    filling = filling_by_area.get(area_number)

    if color_mode == "Electricity price area":
        feature["properties"]["fill_color"] = area_colors[region]
        label = region

    elif color_mode == "Reservoir filling":
        if filling is not None and pd.notna(filling):
            feature["properties"]["fill_color"] = filling_color(filling)
            label = f"{filling:.1%}"
        else:
            feature["properties"]["fill_color"] = [150, 150, 150, 100]
            label = "No data"

    else:
        value = weather_by_area.get(region)

        if value is not None and pd.notna(value):
            feature["properties"]["fill_color"] = weather_color(
                value, weather_min, weather_max, color_mode
            )

            unit = "°C" if color_mode == "Temperature" else "mm"
            label = f"{value:.1f} {unit}"
        else:
            # We don't have saved 2024 weather for NO4/NO5 yet.
            feature["properties"]["fill_color"] = [150, 150, 150, 100]
            label = "No weather data"

    feature["properties"]["value_label"] = label


# Find the ISO week corresponding to the selected NVE observation.
selected_iso_year = int(weekly_data["iso_aar"].iloc[0])
selected_iso_week = int(weekly_data["iso_uke"].iloc[0])

weather_by_area = {}
weather_min = weather_max = None


# Draw semi-transparent polygons with visible outlines.
layer = pdk.Layer(
    "GeoJsonLayer",
    data=colored_areas,
    id="price-areas",
    filled=True,
    stroked=True,
    pickable=True,
    auto_highlight=True,
    get_fill_color="properties.fill_color",
    get_line_color=[40, 70, 110, 255],
    line_width_min_pixels=2,
)

# Display the normal price-area polygons.
layers = [layer]

# Draw a thicker outline around the selected area.
selected_region = st.session_state["map_selected_region"]

if selected_region is not None:
    selected_features = [
        feature for feature in price_areas["features"]
        if feature["properties"]["region"] == selected_region
    ]

    if selected_features:
        highlight_layer = pdk.Layer(
            "GeoJsonLayer",
            data={
                "type": "FeatureCollection",
                "features": selected_features
            },
            id="selected-area-outline",
            filled=False,
            stroked=True,
            pickable=False,
            get_line_color=[255, 160, 50, 255],
            line_width_min_pixels=5
        )

        layers.append(highlight_layer)

# Position the map to show mainland Norway.
view = pdk.ViewState(
    latitude=64.5,
    longitude=14.0,
    zoom=3.7,
    pitch=0,
)

deck = pdk.Deck(
    layers=layers,
    initial_view_state=view,
    map_style=None,
    tooltip={"text": "Area: {region}\nValue: {value_label}"},
)

# Allow users to select one polygon at a time.
event = st.pydeck_chart(
    deck,
    use_container_width=True,
    on_select="rerun",
    selection_mode="single-object",
    key="price_area_map"
)

# Get the selected polygon's index in the GeoJSON feature list.
selected_indices = event.selection.indices.get("price-areas", [])

if selected_indices:
    selected_index = selected_indices[0]
    region = price_areas["features"][selected_index]["properties"]["region"]

    # Save changes and redraw the map with the new highlight.
    if region != st.session_state["map_selected_region"]:
        st.session_state["map_selected_region"] = region
        st.rerun()

# Show the current selection underneath the map.
if st.session_state["map_selected_region"]:
    st.success(
        f"Selected electricity area: {st.session_state['map_selected_region']}"
    )
else:
    st.info("Click an electricity area on the map to select it.")

if color_mode == "Reservoir filling":
    st.caption(
        "Colour scale: orange indicates lower reservoir filling, "
        "while blue indicates higher filling."
    )
else:
    st.caption(
        "Each colour identifies a separate electricity price area. "
        "Hover over a polygon to see its name."
    )

st.caption(
    "Electricity price-area boundaries from NVE Atlas. "
    "Hover over an area to see its identifier."
)

